import * as Blockly from 'blockly';
import { clarifyOptions, clarifyLabel, clarifyMsg } from '../ptClarity.js';
import * as fieldColourPkg from '@blockly/field-colour';
import { OR } from '../generated/orSpecs.js';

// Builds Blockly block definitions from the Open Roberta spec generated by
// scripts/or-generate-specs.mjs (decision 0011). Shape, labels, dropdown options,
// hidden fields, colours, and connection checks come from Open Roberta itself, so
// the sim's blocks match Open Roberta Lab field for field.
//
// Category files call defineOrBlocks([...types]) for plain blocks, and add their own
// behaviour (mutations) for Open Roberta's dynamic blocks.

// The plugin ships as CommonJS; this works under both Vite and plain Node.
const FieldColour = fieldColourPkg.FieldColour || fieldColourPkg.default.FieldColour;

export function orSpec(type) {
  const spec = OR.blocks[type] || OR.extraTypes[type];
  if (!spec) throw new Error(`[orFactory] no Open Roberta spec for block type "${type}"`);
  return spec;
}

export function orMsg(key, fallback = '') {
  return clarifyMsg(key, OR.msg[key] !== undefined ? OR.msg[key] : fallback);
}

// ── Note picker ──────────────────────────────────────────────────────────────
// Open Roberta uses a piano-keyboard field (Blockly.FieldNote) whose value is the
// frequency in Hz and whose text is the note name in German notation (c’, h’, c’’…).
// We approximate it with a dropdown over the same values: two octaves from c’ (C4).
const NOTE_NAMES = ['c', 'c#', 'd', 'd#', 'e', 'f', 'f#', 'g', 'g#', 'a', 'a#', 'h'];
const NOTE_OPTIONS = [];
for (let i = 0; i <= 24; i++) {
  const freq = 261.626 * Math.pow(2, i / 12);
  const octave = i < 12 ? '’' : (i < 24 ? '’’' : '’’’');
  NOTE_OPTIONS.push([`${NOTE_NAMES[i % 12]}${octave}`, freq.toFixed(3)]);
}
export class FieldNote extends Blockly.FieldDropdown {
  constructor(value) {
    super(NOTE_OPTIONS);
    // Snap any stored frequency to the nearest option (OR stores e.g. "261.626").
    const v = Number(value);
    let best = NOTE_OPTIONS[0][1];
    for (const [, f] of NOTE_OPTIONS) if (Math.abs(Number(f) - v) < Math.abs(Number(best) - v)) best = f;
    this.setValue(best);
  }
  doClassValidation_(newValue) {
    if (newValue === null || newValue === undefined) return null;
    const v = Number(newValue);
    if (!Number.isFinite(v)) return null;
    let best = NOTE_OPTIONS[0][1];
    for (const [, f] of NOTE_OPTIONS) if (Math.abs(Number(f) - v) < Math.abs(Number(best) - v)) best = f;
    return best;
  }
}

// ── Field construction ──────────────────────────────────────────────────────

function dropdownOptions(options) {
  // Blockly rejects empty labels; Open Roberta uses them for single-port dropdowns.
  return options.map(([label, value]) => [label === '' ? ' ' : label, value]);
}

/**
 * Creates the Blockly field for one spec field. Returns [field, name|undefined].
 * `type` (the block type) picks the clearer PT-PT text (src/blockly/ptClarity.js).
 */
export function makeField(f, validator, type = '') {
  switch (f.t) {
    case 'label':
      return [new Blockly.FieldLabel(clarifyLabel(type, f.text)), undefined];
    case 'namedLabel':
      // Visible, non-serialised (UNIT, SENSORTITLE, TITLE_FOREVER, RPM, SPACE, GET).
      return [new Blockly.FieldLabel(clarifyLabel(type, f.text)), f.name];
    case 'hidden':
      // Serialised but invisible (ACTORPORT "_D", SENSORPORT "_S", …). appendSpecInput
      // hides it after attaching; callers appending it themselves must do the same.
      return [new Blockly.FieldLabelSerializable(f.value), f.name];
    case 'dropdown': {
      // Set the default before attaching the validator: Blockly runs validators on
      // setValue, and shape-changing validators must not fire during construction.
      const dd = new Blockly.FieldDropdown(dropdownOptions(clarifyOptions(type, f.name, f.options)));
      dd.setValue(f.value);
      if (validator) dd.setValidator(validator);
      return [dd, f.name];
    }
    case 'number':
      return [new Blockly.FieldNumber(f.value), f.name];
    case 'text':
      // FieldTextInput attaches the validator after setting the initial value.
      return [new Blockly.FieldTextInput(f.value, validator), f.name];
    case 'colour':
      return [new FieldColour(f.value), f.name];
    case 'note':
      return [new FieldNote(f.value), f.name];
    default:
      throw new Error(`[orFactory] unknown field kind ${f.t}`);
  }
}

/** Appends one spec input (with its fields) to a block. */
export function appendSpecInput(block, input, validators = {}) {
  let inp;
  if (input.type === 'value') inp = block.appendValueInput(input.name);
  else if (input.type === 'statement') inp = block.appendStatementInput(input.name);
  else inp = input.name ? block.appendDummyInput(input.name) : block.appendDummyInput();
  if (input.check && input.type !== 'dummy') inp.setCheck(input.check);
  for (const f of input.fields) {
    const [field, name] = makeField(f, f.name ? validators[f.name] : undefined, block.type);
    inp.appendField(field, name);
    // Visibility must be applied once the field is attached to the block.
    if (f.t === 'hidden') field.setVisible(false);
  }
  return inp;
}

/** Applies the static part of a spec (inputs, connections, colour) inside init(). */
export function initFromSpec(block, spec, validators = {}) {
  for (const input of spec.inputs) appendSpecInput(block, input, validators);
  if (spec.output !== false) block.setOutput(true, spec.output);
  if (spec.prev) block.setPreviousStatement(true);
  if (spec.next) block.setNextStatement(true);
  if (spec.inline === true || spec.inline === false) block.setInputsInline(spec.inline);
  block.setColour(spec.colour);
}

// ── Sensor "mode" behaviour ─────────────────────────────────────────────────
// Open Roberta sensor blocks store <mutation mode="X"/>; changing MODE changes the
// output type (e.g. quad RGB COLOUR → Colour, LIGHT → Number) and the unit label.

function modeMixin(spec) {
  return {
    updateMode_(mode) {
      this.mode_ = mode;
      const m = spec.modes[mode];
      if (!m) return;
      if (this.outputConnection) this.outputConnection.setCheck(m.output);
      const unit = this.getField('UNIT');
      if (unit) unit.setValue(clarifyLabel(this.type, m.unit));
    },
    mutationToDom() {
      const el = Blockly.utils.xml.createElement('mutation');
      el.setAttribute('mode', this.mode_ || this.getFieldValue('MODE'));
      return el;
    },
    domToMutation(el) {
      this.updateMode_(el.getAttribute('mode'));
    },
    saveExtraState() { return { mode: this.mode_ || this.getFieldValue('MODE') }; },
    loadExtraState(state) { if (state && state.mode) this.updateMode_(state.mode); },
  };
}

/** Defines a plain (or sensor-mode) block straight from its Open Roberta spec. */
export function defineOrBlock(type) {
  const spec = orSpec(type);
  // Sensor blocks always serialise <mutation mode="…"/>, even when MODE is a hidden
  // constant (key/joystick: PRESSED) and has no per-mode variants.
  const hasMode = !!spec.modes || !!(spec.mutation && spec.mutation.mode !== undefined);
  const s = hasMode && !spec.modes ? { ...spec, modes: {} } : spec;
  const def = {
    init() {
      const validators = {};
      if (hasMode) {
        const block = this;
        validators.MODE = function (newValue) { block.updateMode_(newValue); return newValue; };
      }
      initFromSpec(this, s, validators);
      if (hasMode) this.updateMode_(this.getFieldValue('MODE'));
    },
  };
  if (hasMode) Object.assign(def, modeMixin(s));
  Blockly.Blocks[type] = def;
}

export function defineOrBlocks(types) {
  for (const t of types) defineOrBlock(t);
}
